import json, csv, statistics, collections
from pathlib import Path
p=Path(__file__).parent
c=json.loads((p/'live-capture.json').read_text()); real=[x for x in c['cases'] if not x.get('negativeControl')]
# Provisional AI screening from captured titles and provider abstracts, not human judgments.
ratings={
'sanctions-comparison': [('direct','Explicit comparison of responses to sanctions across democratic and authoritarian regimes.'),('direct','Studies sanction effectiveness across regime types, including hybrid regimes.'),('supporting','Explains authoritarian resilience, but does not establish the requested cross-regime comparison.'),('supporting','Examines sanction targeting against authoritarian states rather than comparative effects.'),('off-target','Focus is sender citizens\' preferences, not effects on target regime types.')],
'climate-migration': [('direct','Models climate-related internal migration in Bangladesh.'),('direct','Examines salinity and internal migration in Bangladesh.'),('direct','Qualitative study of internal migration and extreme weather among Bangladeshi fishers.'),('direct','Analyzes hazard-related internal migration using Bangladesh household data.'),('direct','Addresses climate-influenced internal migration and Bangladesh policy.')],
'renewable-energy': [('supporting','Offshore wind and marine mammals fit; no abstract to establish systematic-review methodology.'),('off-target','Primary tracking study, not the requested systematic review.'),('supporting','Monitoring-technology synthesis; systematic-review method is not established.'),('direct','Explicit systematic review including marine mammals among multiple taxonomic groups.'),('supporting','Describes itself as semi-systematic; relevant background but not a confirmed systematic review meeting the full request.')],
'history-primary': [('supporting','Oral history about the 1958 Wichita sit-in organizer; Greensboro 1960 is contextual, not established as the focus.'),('uncertain','Interview format, but no abstract or sufficient metadata to establish the requested event coverage.')],
'new-wearables': [('direct','Adult wearable ECG review explicitly addresses AF detection.'),('direct','Large adult wearable AF detection study.'),('direct','Wearable ECG feasibility study for covert AF in young adults.'),('direct','Adult prospective cohort evaluating a wearable patch for AF detection.'),('direct','Systematic review explicitly includes adults, wearables, and AF diagnostic accuracy.')],
'new-student-ai': [('supporting','Relevant student perceptions of critical thinking; undergraduate eligibility not established in the abstract and self-report is not a causal effect.'),('supporting','Explicit undergraduate sample and AI-related evaluative behavior, but not a direct assessment of changes in critical thinking from AI use.'),('supporting','Direct association between GenAI use and critical-thinking disposition; undergraduate-only population not confirmed from the captured college-student description.'),('supporting','Relevant qualitative perceptions; undergraduate status not confirmed in the abstract.'),('supporting','Relevant experiments and survey, but undergraduate population not confirmed from the abstract.')],
'new-microplastics': [('direct','Agricultural-soil microplastic experiment measuring earthworm growth and mortality.'),('direct','Agricultural contamination and experimental earthworm effects, including additive co-exposure.'),('direct','Agricultural-soil experiment measuring earthworm behavior, biomass and mortality.'),('supporting','Field measurements of contamination in soil and earthworms; biological harm is not directly evaluated.'),('direct','Soil mesocosm study of microplastic/pesticide effects on earthworm growth, reproduction and mortality in an agricultural-pollution context.')]
}
review=[]
for case in c['cases']:
 for s,(label,reason) in zip(case['candidates'][:5],ratings.get(case['id'],[])):
  review.append({'caseId':case['id'],'rank':s['rank'],'title':s['title'],'doi':s.get('doi',''),'aiDiagnosticLabel':label,'reason':reason,'reviewer':'Codex AI; not independent human review'})
counts=dict(collections.Counter(x['aiDiagnosticLabel'] for x in review))
(p/'ai-relevance-screen.json').write_text(json.dumps({'method':'Preselected 12-case screen: 11 real questions plus one negative control. Seven yielded records on the initial pass; all their 32 top-five records were screened from titles and provider abstracts. Failed/empty cases remain in query-level denominators. Direct requires explicit fit to the full requested topic/constraints; supporting means related but a requirement is unconfirmed or missing. Do not equate supporting with assignment compliance. Not an independent, blinded, human or full-text review. Undergraduates are not inferred from generic university-student labels. No causal effect is inferred from self-report or correlation. No scientific-validity grade.','counts':counts,'records':review},indent=2))
slots=[(x,s) for x in real for s in x['candidates'][:5]]
dups=0
for x in real:
 keys=[s.get('doi','').strip().lower() or ''.join(t for t in s['title'].lower() if t.isalnum()) for s in x['candidates'][:5]]
 dups+=len(keys)-len(set(keys))
metrics={'releaseId':c['healthBefore']['releaseId'],'totalRequests':len(c['cases']),'realQueries':len(real),'nonemptyRealQueries':sum(bool(x['candidates']) for x in real),'atLeastFiveRealQueries':sum(len(x['candidates'])>=5 for x in real),'completedSourceStages':sum(x['status']=='captured' for x in real),'topFiveSlotsReturned':len(slots),'detectedWithinQueryTopFiveDuplicates':dups,'medianCompletedSourceStageMs':statistics.median(x['retrieval']['latencyMs'] for x in real if x['status']=='captured'),'timeoutOrProviderTimeoutCases':[x['id'] for x in real if x['status']=='failed' or any(l['status']=='timeout' for l in x.get('sourceDiscovery',{}).get('lanes',{}).values())],'aiRelevanceScreen':counts,'humanRelevanceAccuracy':None,'generatedClaimAccuracy':None}
(p/'metrics.json').write_text(json.dumps(metrics,indent=2))
with (p/'human-review.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['case_id','question','rank','title','url','doi','full_request_fit','identity_checked','source_type_checked','claims_supported','reviewer','notes'])
 for case,s in slots:w.writerow([case['id'],case['query'],s['rank'],s['title'],s['url'],s.get('doi',''),'','','','','',''])
print(json.dumps(metrics,indent=2))
